globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-21 06:45:05 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72.0,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"政府の内部資料流出か、基幹システムに不正アクセス　デジタル庁発表：朝日新聞","url":"https://www.asahi.com/articles/ASVCN30WCVCNULFA01NM.html","source":"Hatena","published_at":"2026-11-20 18:31","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"デジタル庁の基幹システムに不正アクセス、内部資料流出の可能性","summary":"デジタル庁は、政府の基幹ネットワークシステム「GSS」内のファイル共有サービスに対し不正アクセスがあり、内部資料が漏洩した可能性があると発表。7月30日から11月12日の長期間にわたりアクセスを受けていた。\n\n流出した情報には個人情報が含まれる可能性があるが、詳細は調査中。GSSは政府職員が会議資料などをやり取りするシステムであり、9月にも別の不正アクセス被害が発生していた。政府機関のセキュリティ対策の脆弱性が浮き彫りとなっている。","importance":10},{"title":"AIが追加学習なしで自らのウェイトを書き換えて「自分自身を賢くする」ことに成功","url":"https://gigazine.net/news/20261120-large-language-model-can-rewrite-itself/","source":"Hatena","published_at":"2026-11-20 19:11","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIが追加学習なしで自らの重みを書き換え性能向上に成功","summary":"大規模言語モデル（LLM）が、追加学習を行わずに自らのウェイト（重み）を分析・書き換えることで性能を向上させる「Self-Rewriting」という手法が研究論文で発表されました。イリノイ大学などの研究チームは、270億パラメーターのモデルを用いて、数学の問題に対する回答精度を改善することに成功しました。\n\nこの手法では、勾配降下法などの従来の手法を使わず、AI自身が内部状態を分析して問題の原因を特定し、ウェイトを修正します。これはAIによる「再帰的自己改善」の実現に向けた重要な一歩であり、将来的には大規模な計算環境を必要とせずにAIが自律的に能力を高められる可能性を示唆しています。","importance":9},{"title":"プレイド「KARTE」の情報漏洩2200社　サービス停止で20億円の赤字へ - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUC204SK0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-20 16:48","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"プレイド「KARTE」不正アクセス被害、2200社に拡大し赤字転落","summary":"マーケティング支援サービス「KARTE」を提供するプレイドは、不正アクセスによる情報漏洩の被害がのべ約2200社に拡大したと発表しました。サービス停止に伴う影響は甚大で、2026年12月期の業績予想を黒字から20億円の赤字へ大幅に下方修正しました。\n\n漏洩対象には契約終了企業の情報も含まれており、被害の広がりが深刻です。プレイドは1月中旬のサービス再開を目指し、停止期間中の料金を請求しない方針です。今回の事案は、SaaSベンダーにおけるセキュリティ対策が、顧客企業の信頼と自社の経営基盤を直撃するリスクを改めて浮き彫りにしました。","importance":9},{"title":"メモリ圧縮を使えばCPUの処理能力を少し犠牲にするだけでメモリ使用量を大幅に削減できる","url":"https://gigazine.net/news/20261120-memory-compress/","source":"Hatena","published_at":"2026-11-20 15:24","genre":"other","genre_label":"総合・その他IT","headline":"Linuxのメモリ圧縮「zram」活用でRAM増設なしの性能改善","summary":"PCのメモリ不足を解消する手段として、RAMを増設する代わりにCPUでデータを圧縮する「メモリ圧縮」が注目されています。Linux環境では「zram」機能を用いることで、物理メモリ使用量を大幅に削減し、ストレージへのスワップ発生を抑えて動作を改善できます。\n\n検証では、大量のタブを開いた環境でメモリ使用量を約3分の1に圧縮できることが示されました。CPU負荷はわずかに増加しますが、ハードウェアを買い替えることなくシステム全体のレスポンスを向上させられるため、特にリソースが限られた環境やサーバー運用において有効な最適化手法です。","importance":6},{"title":"「httpS://」だと暗号化されず平文で送信……「PHP」に約20年潜んでいた脆弱性が解決／問題はいたってシンプル、なんともはや……【やじうまの杜】","url":"https://forest.watch.impress.co.jp/docs/serial/yajiuma/2158241.html","source":"Hatena","published_at":"2026-11-20 18:26","genre":"web","genre_label":"Web開発・言語","headline":"PHPに20年潜んでいた脆弱性、HTTPSの大文字表記で暗号化が回避される","summary":"PHPにおいて、URLスキームの「https」を「HTTPS」のように大文字で記述すると、TLSによる暗号化が行われず平文で通信されるという脆弱性が発見されました。この問題は20年以上前から存在しており、深刻度は「High」と評価されています。\n\n原因は、PHPのストリームラッパーがスキームの大文字・小文字を区別せず受け入れる一方で、暗号化判定が小文字の「s」に依存していたことにあります。パスワードや認証トークンが漏洩するリスクがあるため、最新版へのアップデートが必須です。修正できない場合は、スキームを小文字に正規化するなどの回避策が必要です。","importance":8},{"title":"初心者がAIとMAXのAPKを解析してみた","url":"https://zenn.dev/aki0804/articles/d4ec272cf5f871","source":"Zenn","published_at":"2026-11-20 10:34","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AIエージェントを活用したAndroidアプリ「MAX」の静的解析レポート","summary":"ロシアのスマホにプリインストールされているメッセンジャーアプリ「MAX」を対象に、リバースエンジニアリング初心者による解析を実施。AIエージェントの補助を受け、本文送信処理やVPN制限、診断データの送信仕様を調査した。\n\nJADXによるコード復元や隔離環境での試験を通じて、サーバー側で本文を復元可能な設計であることを確認。VPN利用時の返信制御や診断情報の送信条件についても詳細な分析を行っており、モバイルアプリのセキュリティ調査手法として興味深い。","importance":6},{"title":"政府システムからファイル流出か、個人情報含む恐れ　デジタル庁発表 - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUA20A0V0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-20 22:10","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"デジタル庁の政府ネットワークで不正アクセス、内部資料流出の可能性","summary":"デジタル庁は、政府共通のネットワーク環境「ガバメントソリューションサービス（GSS）」への不正アクセスを検知し、会議資料を含むファイルが流出した可能性があると発表しました。7月30日から11月12日にかけて複数回のアクセスが確認されており、個人情報が含まれている恐れがあります。\n\nGSSは25の政府機関が利用する基幹システムであり、現在はサービスを停止して調査が進められています。政府は9月にも別の不正アクセスによる情報漏洩を公表しており、サイバーセキュリティ対策の脆弱性が改めて浮き彫りとなりました。警察や専門機関と連携し、被害の全容解明と再発防止が急務となっています。","importance":9},{"title":"万博跡地は今どこまで更地になった？ 衛星の SAR 強度と夜間光で追ってみた（Sentinel-1 × VIIRS）","url":"https://zenn.dev/syu_tan/articles/002_expo_site_sar","source":"Zenn","published_at":"2026-11-20 11:45","genre":"other","genre_label":"総合・その他IT","headline":"衛星データ（SAR×夜間光）で追う大阪万博跡地の解体プロセス","summary":"2025年大阪・関西万博の閉幕後、会場跡地がどのように更地化されたかをSentinel-1のSAR強度画像と夜間光データを用いて分析。SARの特性である「立っている物の反射」を利用し、パビリオンや大屋根リングの解体状況を時系列で可視化した。\n\n光学衛星とは異なり雲の影響を受けないSARの利点を活かし、区域ごとの解体進捗を定量的に追跡。技術的な解析手法と、大規模イベント後の都市インフラの変化を宇宙から観測する興味深い事例となっている。","importance":6},{"title":"自分の代わりに動くAgentへ。Claude CodeとCodexで作る自律改善ハーネス","url":"https://zenn.dev/nttdata_tech/articles/9562962cc181a1","source":"Hatena","published_at":"2026-11-20 08:35","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude CodeとCodexを活用した自律的な開発環境「ハーネス」の構築術","summary":"AIエージェントに業務を自律的に任せるため、モデルの外側に「ハーネス」と呼ばれる制御構造を構築する手法を解説。プロンプトの工夫よりも、フォルダ構成やタスク管理の仕組みを整備することで、エージェントが自律的に作業・検査・整理を行える環境を実現した。\n\n具体的には、規約と記録をGitリポジトリに集約し、タスク単位での管理やスクリプトによる自動検査を導入。これにより、複数のセッションを並行して走らせ、人間は確認と判断に集中する運用が可能となり、開発効率が大幅に向上した。","importance":9},{"title":"TSMCやサムスン、対中半導体出荷を一部停止　AIチップの米輸出規制で - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOGN200HL0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-20 16:34","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"TSMCとサムスンが中国向け半導体出荷を一部停止、米規制強化の影響","summary":"米政府によるAI半導体の対中輸出規制強化を受け、台湾のTSMCと韓国のサムスン電子が中国顧客への一部半導体出荷を停止しました。この動きは、中国のAI開発環境に大きな制約を与える可能性があり、業界内では警戒感が強まっています。\n\n今回の措置は、米国の先端技術輸出管理が厳格化されている現状を反映しています。中国側は半導体の自給自足体制の構築を急いでいますが、主要サプライヤーの供給停止は、AI開発のスピードやコストに直結する重要な転換点となります。","importance":9},{"title":"検索を速くすると、代わりに何が重くなるのか","url":"https://zenn.dev/loglass/articles/9f1c9da491fefa","source":"Zenn","published_at":"2026-11-20 12:00","genre":"web","genre_label":"Web開発・言語","headline":"PostgreSQLの検索高速化手法におけるトレードオフを定量比較","summary":"PostgreSQLにおける検索高速化手法（GIN index、生成列、MATERIALIZED VIEW）について、検索速度と引き換えに発生する書き込み負荷や容量増加のコストを定量的に比較検証した。\n\n特にGIN indexの容量や、生成列を用いた正規化による検索高速化の効果を実データで測定。検索の高速化は「読む行を減らす」ことだが、その代償として書き込み時の計算コストやストレージ消費が増えるというトレードオフを明確にし、要件に応じた最適な手段選定の指針を示している。","importance":8},{"title":"はてなエンジニアの自作RSSリーダーをご紹介します 2026 - Hatena Developer Blog","url":"https://developer.hatenastaff.com/entry/2026/11/20/162322","source":"Hatena","published_at":"2026-11-20 17:33","genre":"other","genre_label":"総合・その他IT","headline":"はてなエンジニアによる自作RSSリーダーの多様な活用事例","summary":"はてなエンジニアたちが業務外で自作したRSSリーダーの事例が紹介されています。キーボード操作にこだわったもの、SNSのようにタイムライン形式で閲覧するもの、機械学習で記事を分類するものなど、個人の好みが色濃く反映されたツールが並びます。\n\n生成AIの普及により、個人開発のハードルは大幅に下がっています。技術的な興味を満たすだけでなく、自身の情報収集スタイルを最適化するための自作ツール開発は、エンジニアにとって有意義なアウトプットです。この記事は、読者に対して自作RSSリーダー開発のモチベーションを刺激する内容となっています。","importance":4},{"title":"RTKの走行データ収集でAndroidの記録アプリを外から監視する","url":"https://zenn.dev/nauh_blog/articles/b60cd6973c8a3f","source":"Zenn","published_at":"2026-11-20 18:00","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AndroidアプリのRTK走行データを外部から監視する仕組みの構築","summary":"RTK測位を用いた車両走行データの収集において、記録アプリ「DroggerGPS」の状態をリアルタイムで監視するAndroidアプリを自作した事例が紹介されています。走行中の記録停止や測位精度の低下を即座に検知し、管理画面から遠隔で状況を把握・対処することで、走行のやり直しを防ぐ仕組みです。\n\n監視アプリは、Androidのプロセス間通信やNMEAセンテンスの解析を組み合わせ、15秒ごとに状態をサーバーへ送信します。通信はHTTPSのみを利用し、携帯回線のNAT環境下でも安定した運用を実現しています。現場での効率的なデータ収集を支える、実用的なエンジニアリングの好例です。","importance":5},{"title":"政府の内部資料流出か、基幹システムに不正アクセス　デジタル庁発表：朝日新聞","url":"https://www.asahi.com/sp/articles/ASVCN30WCVCNULFA01NM.html?linkType=article&id=ASVCN30WCVCNULFA01NM","source":"Hatena","published_at":"2026-11-20 19:55","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"デジタル庁GSSへの不正アクセス、政府内部資料流出の懸念","summary":"デジタル庁は、政府の基幹ネットワーク「ガバメントソリューションサービス（GSS）」に対する不正アクセスを公表しました。7月30日から11月12日までの期間に、ファイル共有サービスが攻撃を受け、内部資料や個人情報が流出した可能性があります。\n\nGSSは現在、総務省や内閣府など25機関の約15万人が利用する重要なインフラです。デジタル庁は12日に当該サービスを停止し、詳細な調査を開始しました。政府は9月にも大規模な個人情報流出を経験しており、今回の事案は政府システムのセキュリティ体制に対する信頼をさらに揺るがす事態となっています。","importance":9},{"title":"Codex App の Computer Use はどういう仕組みで動いているのか - Qiita","url":"https://qiita.com/TaigoKuriyama/items/850a26760fc3c8d111ad","source":"Hatena","published_at":"2026-11-20 14:38","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Codex AppのComputer Use機能、MCPサーバーによるUI操作の仕組み","summary":"AIがローカルアプリを操作する「Computer Use」機能が、Codex Appでどのように実装されているかを解説しています。この機能は、画面状態を読み取り、クリックや入力などの操作をループで実行する仕組みです。\n\nCodex Appでは、MCPサーバーとSkillを組み合わせたプラグインとして提供されており、SkyComputerUseClientがUI操作のプリミティブを実行します。Skillは操作のガードレールをAIに教える役割を担っており、セキュリティと実用性を両立させるためのアーキテクチャが明らかになりました。","importance":8},{"title":"斜め上からやってきた「SaaSの死」｜ninoya 古越","url":"https://note.com/aatoku/n/n129df4db50ba","source":"Hatena","published_at":"2026-11-20 13:28","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"データ流出リスクが招く「SaaSの死」とAXへの転換","summary":"相次ぐSaaSでの情報漏えい事件を受け、企業がデータを外部に預けることへの警戒感が強まっています。これにより、ロックインを前提とした従来のSaaSビジネスモデルが揺らいでいます。\n\n今後は、データを自社環境に置いたままAIを活用してシステムを構築する「AX（AI Transformation）」が勢いを増すと予測されます。営業コストをかけて囲い込むモデルから、AIを活用して低コストで柔軟に構築するモデルへの転換が、SaaS業界に新たなゲームチェンジをもたらそうとしています。","importance":9},{"title":"Rails の ActionController::Live × gRPC Server Streaming で、AI の返答をリアルタイム","url":"https://zenn.dev/flyingclouds/articles/2b6fa8c0e86a14","source":"Zenn","published_at":"2026-11-20 11:19","genre":"web","genre_label":"Web開発・言語","headline":"RailsとgRPC Server Streamingを組み合わせたAI返答のリアルタイム表示","summary":"Rails 8.1とPythonのAIサービスをgRPCで接続し、AIの生成結果をブラウザへリアルタイムにストリーミング表示する構成を紹介。ActionController::LiveとSSEを活用し、効率的なデータ転送を実現した。\n\nPumaのfork問題への対応や、ユーザーがタブを閉じた際の処理、ストリーミングの冪等性確保など、本番運用で不可欠なポイントを網羅。WebSocketを使わずともSSEで十分な一方向ストリーミングの設計指針として有用である。","importance":8},{"title":"丸井G、顧客情報延べ1733万件が漏洩　委託先に不正アクセス - 日本経済新聞","url":"https://www.nikkei.com/article/DGXZQOUC209MW0Q6A121C2000000/","source":"Hatena","published_at":"2026-11-20 19:38","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"丸井グループ、委託先への不正アクセスで1733万件の顧客情報が漏洩","summary":"丸井グループは、委託先のプレイドが提供するサービス「KARTE」への不正アクセスにより、延べ1733万件の顧客情報が漏洩したと発表。ECサイト利用者やエポスカード利用者の氏名、生年月日、メールアドレスなどが含まれる。\n\n現時点でクレジットカード情報の漏洩や不正利用は確認されていないが、委託先システムとのアクセスを遮断し調査を進めている。サプライチェーン攻撃による被害が拡大しており、委託先のセキュリティ管理が改めて問われている。","importance":9},{"title":"同じ内容でも言語でトークン数は何倍違う？日本語・中国語・韓国語・タイ語を6つのトークナイザーで比べてみた","url":"https://zenn.dev/aiforall/articles/5069b7c19696bf","source":"Zenn","published_at":"2026-11-20 12:06","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"言語別トークン数比較：日本語・中国語・韓国語・タイ語のコスト差を検証","summary":"LLMのAPI料金やコンテキスト消費に直結する「トークン数」について、6つのトークナイザーを用いて英語と他言語（日・中・韓・タイ）の比率を比較検証。日本語は英語の約1.9倍、タイ語は最大4.4倍のトークンを消費することが判明した。\n\nモデルの世代交代により英語以外の言語のトークン効率は改善傾向にあるが、依然として言語による差は大きい。語彙に含まれる言語ほど効率が良いという原則を再確認し、コスト最適化のためのトークナイザー選定の重要性を提示している。","importance":8},{"title":"「あと10年もたないかもしれない」Rubyの父 まつもとゆきひろが危惧するOSS文化の消滅 - エンジニアtype | 転職type","url":"https://type.jp/et/feature/32219/","source":"Hatena","published_at":"2026-11-20 13:31","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"まつもとゆきひろ氏が語るOSS文化の危機と持続可能性","summary":"Rubyの生みの親であるまつもとゆきひろ氏が、OSS文化の存続に対する強い危機感を表明しました。AIの普及によりOSSの貢献が見えにくくなる一方で、開発者の負担は増大しており、基盤技術の安全性維持が困難になりつつあります。\n\n企業によるOSS支援の難しさや、コミュニティの疲弊が指摘されています。OSSが失われることはエンジニアにとっての未来を閉ざすことにも繋がりかねず、持続可能な開発モデルの再構築が急務となっています。","importance":8},{"title":"Rails から Python のサービスを gRPC で呼ぶ：はじめてでも本番で使える構成ガイド","url":"https://zenn.dev/flyingclouds/articles/d11dd921ca756b","source":"Zenn","published_at":"2026-11-20 11:18","genre":"web","genre_label":"Web開発・言語","headline":"RailsからPythonサービスをgRPCで呼ぶ本番向け構成ガイド","summary":"RailsからPythonのAIサービスをgRPCで呼び出すための、proto定義からコード生成、クライアント実装、テストまでの一連の流れを解説。protoを「契約書」として扱い、型安全かつ効率的な通信を実現する手法を提示した。\n\nPumaのfork問題への対処や、エラーハンドリングの抽象化など、本番環境で安心して使えるためのベストプラクティスを網羅。言語間連携における堅牢なアーキテクチャ設計の参考となる。","importance":8},{"title":"【速報】三井住友銀で情報漏えい、最大1400万件","url":"https://www.47news.jp/15262461.html","source":"Hatena","published_at":"2026-11-20 19:10","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"三井住友銀行で最大1400万件の顧客情報漏洩の可能性","summary":"三井住友銀行は、業務委託先である株式会社プレイドが提供するサービス「KARTE」が不正アクセスを受けた影響で、最大約1400万件の顧客情報が漏洩した可能性があると発表しました。\n\nマーケティング支援ツールとして広く利用されているサービスが標的となったことで、多くの企業に被害が拡大しています。金融機関という高いセキュリティが求められる業種においても、委託先の管理体制が直接的なリスクとなることが示されました。今後の被害拡大防止と、再発防止策の徹底が強く求められています。","importance":9},{"title":"KaggleのポケモンカードAI対戦コンペ(PTCG AI Battle Challenge)の解法と学び","url":"https://zenn.dev/retrieva_tech/articles/8a1fa7ae2e28ee","source":"Zenn","published_at":"2026-11-20 14:47","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"KaggleポケモンカードAI対戦コンペの解法、模倣学習と強化学習の活用","summary":"Kaggleで開催されたポケモンカードAI対戦コンペにおいて、銀メダルを獲得したチームの解法が公開されました。探索を行わず、Transformerを用いたモデルによる方策決定を主軸とし、上位エージェントの対戦ログを用いた模倣学習と強化学習を組み合わせて性能を向上させました。\n\n特に、盤面情報の適切なトークン化や、合法手の曖昧さを解消する前処理が勝率に大きく寄与しました。探索に頼らないモデル設計は計算リソースの制約下で有効であり、強化学習における価値ヘッドの活用など、ゲームAI開発における実践的な知見が詰まっています。","importance":7},{"title":"情報漏洩3億件超の時代、経営者が問われるのは「どう守るか」よりも「何を持たないか」、顧客情報を預かる資格 KARTEへの不正アクセスとソースネクストの大量流出が示した、顧客情報を持ちすぎる経営の死角 | JBpress (ジェイビープレス)","url":"https://jbpress.ismedia.jp/articles/-/98148","source":"Hatena","published_at":"2026-11-20 20:43","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"情報漏洩時代、経営者に求められる「持たない経営」という視点","summary":"相次ぐ大規模な情報漏洩事案を受け、企業経営におけるデータ管理のあり方が問われています。特にクラウド依存度が高い現代において、経営陣が技術的リテラシーを欠いたまま顧客情報を過剰に保持し続けることは、重大な経営リスクとなります。\n\n現場のエンジニアが脆弱性対応に追われ、予算や裁量を与えられない構造的な問題が指摘されています。今後は「どう守るか」という技術的対策だけでなく、そもそも「何を持たないか」というデータ最小化の戦略や、経営層が自社の情報資産を正しく理解し説明責任を果たす姿勢が、企業の存続を左右する重要な要素となります。","importance":7},{"title":"巨大なAPI Gateway用OpenAPI(Swagger)ファイルをTypeSpecで整理整頓","url":"https://zenn.dev/cariot_dev/articles/70944a671647a8","source":"Zenn","published_at":"2026-11-20 17:44","genre":"web","genre_label":"Web開発・言語","headline":"巨大なOpenAPI定義をTypeSpecで整理・管理する手法","summary":"15,000行を超える巨大なOpenAPI（Swagger）定義ファイルを、Microsoft製のAPI定義DSL「TypeSpec」へ移行した取り組みが紹介されています。TypeScriptライクな構文による高いメンテナンス性と、ファイル分割の容易さが導入の決め手となりました。\n\n移行にあたっては、現行のOpenAPI 2.0から3.0への変換を同時に行い、出力結果が一致することをガードレールとしてリファクタリングを進めました。TypeSpecのデコレータを活用することで、CRUD操作ごとのプロパティ出し分けやベンダー拡張の管理も効率化されています。大規模API管理に悩む開発者にとって有益な知見です。","importance":7},{"title":"「KARTE」への不正アクセスに関する当社調査結果と、サービス再開の見通し等のお知らせ","url":"https://plaid.co.jp/news/20261120/","source":"Hatena","published_at":"2026-11-20 15:33","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"KARTE不正アクセス調査結果、脆弱性悪用による情報漏えいの詳細","summary":"株式会社プレイドが提供する「KARTE」で発生した不正アクセスについて、調査結果と今後の対応が発表されました。公開経路の脆弱性が悪用され、認証情報が盗まれたことで管理画面への不正アクセスが発生し、顧客データの一部が漏えいしました。\n\n同社は全サービスを一時停止し、セキュリティ対策を強化した上で再開を目指しています。今回の事案では、契約終了後の企業データが適切に削除されていなかった管理体制の不備も判明しました。SaaSにおけるデータ管理の重要性と、人的オペレーションを含むセキュリティ運用の見直しが強く求められています。","importance":9},{"title":"Strix HaloにおけるLemonadeの推論速度・精度評価","url":"https://zenn.dev/anjn/articles/05cbd04f980f56","source":"Zenn","published_at":"2026-11-20 12:46","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Strix Halo環境におけるQwenモデルの推論速度と精度を比較検証","summary":"128GBメモリ搭載のStrix Halo機を用い、Qwen系列の3モデル（27B/35B-A3B/Flash-Next）計8構成で推論速度と精度を評価。量子化や生成方式（MTP等）の違いがパフォーマンスに与える影響を測定した。\n\n検証の結果、Qwen3.8-Flash-NextをHalogenで動かす構成が最も実用的で高精度であることを確認。また、思考中の反復現象に対し、出力枠を制御する仕組みが有効であることも示された。ローカルLLMの実運用における構成選定の参考となる。","importance":7},{"title":"「Microsoft To Do」アプリが2027年6月で廃止、個人の場合は別アプリへの乗り換えが必要に／法人向けは「Planner」が後継","url":"https://forest.watch.impress.co.jp/docs/news/2158040.html","source":"Hatena","published_at":"2026-11-20 15:00","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Microsoft To Doが2027年6月で廃止、法人向けはPlannerへ移行","summary":"Microsoftはタスク管理アプリ「Microsoft To Do」を2027年6月30日で終了すると発表しました。個人アカウント向けの後継アプリは用意されず、法人向けには「Microsoft Planner」が統合・後継サービスとなります。\n\n既存のタスクデータはPlannerへ自動移行されないため、ユーザーは期限までにエクスポート等の対応が必要です。今回の決定は、Microsoftのタスク管理機能をPlannerに集約する戦略の一環であり、デスクトップアプリの廃止や機能差異など、既存ユーザーには大きな影響が予想されます。","importance":7},{"title":"AIが爆速で開発する時代の、自動テストとの向き合い方","url":"https://zenn.dev/daiaoki/articles/webterm-ai-era-testing","source":"Zenn","published_at":"2026-11-19 16:11","genre":"web","genre_label":"Web開発・言語","headline":"AI開発時代における個人開発サービスの自動テスト戦略","summary":"AIによる爆速開発環境下で、個人開発サービス「WebTerm Learn」の品質を維持するための自動テスト戦略を解説。ブラウザ上で動作するTypeScript製シミュレーターを開発し、副作用のない関数として実装することでテスト容易性を確保した。\n\n「Functional Core, Imperative Shell」の設計思想に基づき、テストコードを拡充。AIにコードを書かせる一方で、テストという「人の目」を自動化することで、開発速度と品質の両立を実現している。","importance":8},{"title":"脆弱性検査のあとに取った対策 — 見つかった穴を「機械で止める」仕組みへ","url":"https://zenn.dev/doreens/articles/457ea6852608a9","source":"Zenn","published_at":"2026-11-20 12:00","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"脆弱性検査後の対策：手動修正から「機械で止める」仕組みへの転換","summary":"2回の脆弱性検査で判明したセキュリティ上の穴に対し、単なる修正にとどまらず、再発防止のための自動化施策を導入。セキュリティ観点のテスト不足を解消するため、認可テスト行列の生成やCIでの静的解析を強化した。\n\n重大度に応じた対応方針の策定や、外部サービスとの連携における権限管理の厳格化など、開発プロセス全体をセキュアにするための具体的な計画が示されている。セキュリティを「仕組み」で担保する重要性を説く実践的なレポート。","importance":9},{"title":"Decision ModelはFAQの回答の確認と問い合わせの振り分けに使えるか","url":"https://zenn.dev/genax_corp/articles/20261109-judge-models-faq-check","source":"Zenn","published_at":"2026-11-20 12:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"FAQ対応におけるDecision Modelの活用可能性と限界を検証","summary":"文章生成を行わず判定結果のみを返す「Decision Model（Jev, Decisions API, Clef）」を、FAQの回答確認や問い合わせ振り分けに活用できるか検証。生成LLMと比較して、回答の矛盾検知では同等の性能を発揮し、応答時間や費用面で優位性があることがわかった。\n\n一方で、複雑なカテゴリー推定では生成LLMに軍配が上がるなど、用途に応じた使い分けが重要となる。閾値設定の工夫や、RAGの事後フィルターとしての活用など、実務的な知見が共有されている。","importance":7},{"title":"必死で資料を作った会議、上役の「直近のセキュリティ危機は大丈夫なのか」って質問に上司が「あなたが予算を減らしたのでダメです」って返して15分で終わった","url":"https://togetter.com/li/2772854","source":"Hatena","published_at":"2026-11-20 18:29","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"セキュリティ予算削減を指摘された上役が会議で論破される事案","summary":"ある企業で、セキュリティ対策の必要性を訴える会議において、予算を削減し続けてきた上役が、現場の上司から「予算がないため対策は不可能」と明確に指摘され、会議が即座に終了したというエピソードが話題となっています。\n\nこの事例は、現場の危機感と経営層の予算配分の乖離を象徴しています。セキュリティ対策はコストセンターと見なされがちですが、インシデント発生時の経営的ダメージを考慮すれば、適切な投資は不可欠です。現場のエンジニアが理論武装し、経営層にリスクを正しく認識させることの重要性が浮き彫りとなりました。","importance":6},{"title":"Go runtime - Bootstrap","url":"https://zenn.dev/aqyuki/articles/go-runtime-bootstrap","source":"Zenn","published_at":"2026-11-20 17:40","genre":"web","genre_label":"Web開発・言語","headline":"Goランタイムの起動プロセス「Bootstrap」の仕組みを解説","summary":"Go言語のランタイムがプログラム起動時に行う初期化処理「Bootstrap」についての詳細な解説です。OSスレッド（M）やゴルーチン（G）、仮想CPU（P）の初期化から、`runtime.main`の実行に至るまでの流れが、アーキテクチャごとに説明されています。\n\n特に、レジスタからの引数退避、TLSの初期化、スケジューラーやメモリアロケーターの準備といった低レイヤーの処理が順を追って解説されており、Goの内部動作を深く理解するための貴重な資料となっています。ランタイムの挙動を把握することは、パフォーマンスチューニングやトラブルシューティングにおいて重要です。","importance":6},{"title":"CDKからTerraformへ：所有権移譲による本番インフラ無停止のIaC移行","url":"https://zenn.dev/levtech/articles/14befd8e727f32","source":"Zenn","published_at":"2026-11-20 10:26","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"CDKからTerraformへ：所有権移譲による無停止IaC移行手法","summary":"AWS CDK v1からTerraformへのIaC移行において、リソースを一度削除するのではなく「所有権を移譲する」手法を採用し、本番環境を停止させずに移行を完遂した事例。既存リソースのRemovalPolicyをRETAINに設定し、Terraform側でimportすることで安全に管理を切り替えた。\n\nIaC統一による運用コスト削減やセキュリティ対応の効率化など、移行の動機から具体的な手順、ハマりどころまでを網羅。大規模なインフラ移行を検討するチームにとって非常に有益なナレッジである。","importance":9},{"title":"先頭に貼るだけのキラープロンプト7選、コピペOK。→「所見を頼む前に「中学校の担任として、前向きな言葉で」と1行足すだけで、書き直しが半分に減りました。」","url":"https://posfie.com/@techjiho/p/3QDGKHH","source":"Hatena","published_at":"2026-11-20 11:23","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"生成AIの回答精度を劇的に変える先頭付与プロンプト7選","summary":"ChatGPTやClaudeなどの生成AIの回答品質を向上させる、プロンプトの先頭に貼るだけの「キラープロンプト」7選を紹介。専門家モードや結論ファースト、自己検算モードなど、指示を工夫するだけで回答の専門性や論理性が大幅に改善する。\n\n単なるコピペ活用だけでなく、批判的思考の導入や出典確認の徹底など、AIを使いこなすためのリテラシー向上にも言及。実務での書き直し作業を減らすための実践的なテクニックとして注目されている。","importance":7},{"title":"職業訓練でHTMLを学んだ後にSES会社に入社、Javaとphpの開発経験ありと経歴詐称でPythonの現場に送り込まれ、初日にリーダーから「君何ができんの？」と詰められた話","url":"https://togetter.com/li/2772850","source":"Hatena","published_at":"2026-11-20 18:24","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"SES現場での経歴詐称と新人エンジニアの苦悩、業界の闇を告発","summary":"職業訓練でHTMLを学んだだけのエンジニアが、SES会社によって経歴詐称をさせられ、スキル不足のまま開発現場に送り込まれるという実体験が注目を集めています。現場で即座に能力不足を露呈し、精神的に追い詰められるという構造的な問題が浮き彫りとなりました。\n\nSES業界における人手不足を背景とした経歴詐称は、現場のエンジニアに過度な負担を強いるだけでなく、プロジェクトの進行を阻害する重大な問題です。エンジニア自身のスキルアップ努力も必要ですが、営業による無理なアサインや、企業間の契約形態に起因する構造的な改善が求められています。","importance":6},{"title":"Spring ProfileでAWSとAWS Emulatorを切り替える","url":"https://zenn.dev/enchanter_one/articles/e8a849e6080f80","source":"Zenn","published_at":"2026-11-20 14:59","genre":"web","genre_label":"Web開発・言語","headline":"Spring Profileを活用したAWSとエミュレータの環境切り替え","summary":"Spring Bootアプリケーションにおいて、本番のAWS環境とローカル開発用のAWSエミュレータを「Spring Profile」で切り替える手法が紹介されています。コード変更や環境変数の再設定を不要にし、設定ファイルのみで接続先を制御します。\n\nAWS Emulatorを使用することで、テストの独立性を高めつつ、統合テストや日常的な動作確認を効率化できます。AWS SDKのClientをBeanとしてDIすることで、環境に応じたエンドポイントを自動的に適用する設計は、開発効率とテストの信頼性を両立させるための優れたプラクティスです。","importance":6},{"title":"業務委託先への不正アクセスによる情報漏えいについて","url":"https://www.smbc.co.jp/news/pdf/j20261120_01.pdf","source":"Hatena","published_at":"2026-11-20 19:50","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"三井住友銀行、業務委託先「KARTE」への不正アクセスで情報漏洩","summary":"三井住友銀行は、同行のWebサイトやスマートフォンアプリで利用している株式会社プレイドのサービス「KARTE」が不正アクセスを受けたことを受け、顧客情報が漏洩した可能性があると発表しました。\n\n本件は、業務委託先のセキュリティインシデントが大手金融機関の顧客データに波及した事例です。現在、詳細な影響範囲や流出した情報の特定が進められており、顧客への影響を最小限に抑えるための対応が急がれています。サプライチェーン全体でのセキュリティ管理の重要性が改めて強調される結果となりました。","importance":8},{"title":"MetaのMuseを使ってみた: 内部構造とセキュリティの調査","url":"https://zenn.dev/shoyataguchi/articles/b1bc6a96d4b963","source":"Zenn","published_at":"2026-11-20 00:55","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"MetaのAIアシスタント「Muse」の内部構造とセキュリティ設計の分析","summary":"Metaが提供するAIアシスタント「Muse」のUXと内部構造を調査。メインチャットとサイドチャットを使い分け、長期記憶を保持する仕組みや、ユーザー専用のLinux環境でShellやcronを操作できる点が特徴である。\n\n記憶機構にはGraphRAGに近い手法で会話から事実を抽出する仕組みを採用。また、セキュリティへの投資が差別化要因となっており、システムプロンプトのカスタマイズや安全なエージェント運用を重視した設計がなされている。","importance":8},{"title":"Dockerfileでイメージを作成後、レイヤーとキャッシュの確認","url":"https://zenn.dev/mutsu_zenn/articles/75498c3f4e693b","source":"Zenn","published_at":"2026-11-20 07:00","genre":"web","genre_label":"Web開発・言語","headline":"Dockerfileのレイヤー構造とキャッシュの仕組みを実践的に理解する","summary":"Dockerfileの命令がレイヤーとしてキャッシュされる仕組みを、Pythonライブラリのインストールを例に解説。キャッシュはファイルの中身と直前のレイヤーが一致するかで判定されるため、変更頻度の低い命令を上に記述する最適化が重要である。\n\nまた、docker historyやdocker system dfを用いたレイヤー確認、疑似端末（TTY）を割り当てる-tオプションの重要性など、コンテナイメージの軽量化とビルド効率化のための実践的な知見をまとめている。","importance":6},{"title":"POS端末700台超がマルウェア感染、Windowsの脆弱性悪用でカード情報100万件超が流出","url":"https://news.mynavi.jp/techplus/article/20261120-5367457/","source":"Hatena","published_at":"2026-11-20 18:57","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Windows脆弱性悪用でPOS端末700台超が感染、100万件超のカード情報流出","summary":"世界20カ国以上で、Windows搭載のPOS端末700台以上がマルウェアに感染し、100万件を超えるクレジットカード情報が窃取される被害が発生しました。攻撃には2024年12月に修正済みの脆弱性「CVE-2024-49138」が悪用されています。\n\n攻撃者は公開されていたPoCコードを悪用し、SYSTEM権限を取得してカード情報を収集していました。被害の多くはブラジルに集中しており、長期間セキュリティ更新を怠っていた端末が標的となりました。企業には、POS端末を含む全デバイスのパッチ適用状況の再確認と、不審な通信の監視強化が強く推奨されます。","importance":8},{"title":"ドンキのAI社員「近藤あい」が正式デビュー　販促POPや動画で活躍へ　運営元「すでに裏に20人ぐらいいる」","url":"https://www.itmedia.co.jp/news/article/2611/20/2000003369/","source":"Hatena","published_at":"2026-11-20 15:50","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ドンキのAI社員「近藤あい」がデビュー、販促効率化とキャラクター戦略","summary":"ドン・キホーテを運営するPPIHが、生成AIで制作したAI社員「近藤あい」を正式デビューさせます。販促POPや動画制作のコスト削減とスピードアップを狙い、若年層に親しまれるキャラクターとしてSNSや店頭で活用されます。\n\n開発には約1年半を要し、複数の生成AI技術を組み合わせて自然な表情や動きを再現しています。同社は既に裏で約20人のAIキャラクターを準備しており、今後はAI社員による販促活動が本格化する見込みです。AI活用による業務効率化とブランドイメージ向上の両立が注目されます。","importance":6},{"title":"dbt v1 でメトリクスを一元管理する未来 〜Apache Ossie と Lightdash で試す〜","url":"https://zenn.dev/kyami/articles/dbt-snowflake-apache-ossie","source":"Zenn","published_at":"2026-11-19 22:48","genre":"web","genre_label":"Web開発・言語","headline":"dbt v1とApache Ossieによるメトリクス一元管理の現状","summary":"dbtで定義したメトリクスをSnowflakeのSemantic Viewに変換し、BIツール（Lightdash）と共有する仕組みを検証。これまでdbtとSnowflakeで二重管理されていたメトリクス定義を解消する試みである。\n\nApache Ossieを介することで、dbtのYAML定義からウェアハウスネイティブなオブジェクトを生成可能。現時点では発展途上だが、Cortex Analyst等のAI活用を含め、管理コスト削減に向けた重要なステップとなっている。","importance":7},{"title":"Amazon Cognito のトークン交換を試し、AgentCore Gateway の Outbound Auth に組み込む","url":"https://zenn.dev/exwzd/articles/20261116-cognito-token-exchange","source":"Zenn","published_at":"2026-11-20 16:08","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Amazon CognitoがOAuth 2.0トークン交換に対応、OBOの実装が容易に","summary":"Amazon CognitoのユーザープールがOAuth 2.0のトークン交換（RFC 8693）に対応しました。これにより、エージェントがユーザーの代わりに下流のAPIを呼び出す際、スコープを絞ったトークンへ交換する「On-behalf-of（OBO）」フローをCognito単体で完結できるようになりました。\n\n従来は自前での実装が必要だったトークン交換が標準機能として提供されたことで、セキュリティと開発効率が大幅に向上します。特にエージェントがユーザーの権限を安全に代理実行する際の認可フローが簡素化され、より堅牢なシステム設計が可能になります。","importance":8},{"title":"日本のレシートを自宅PCでOCRする：15構成を実レシート11枚で比べた","url":"https://zenn.dev/chaki/articles/4545be3475fdb4","source":"Zenn","published_at":"2026-11-20 13:33","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"自宅PCでのレシートOCR、15構成の比較検証結果","summary":"自宅のミニPC環境で、日本のレシートをOCRで読み取るための最適な構成を検証したレポートです。YomiTokuが商品名の一致度や速度で高い性能を示し、商用利用ではNDLOCR-LiteやPP-OCRv6が現実的な候補となることが分かりました。\n\nVLM型AIは手書き領収書には強いものの、長いレシートでは精度が低下する傾向があります。NVIDIA GPUなしの環境でも、軽量モデルと2段読み手法を組み合わせることで高い実用性を確保できることが証明されました。セルフホスト環境でのOCR構築における貴重なベンチマークです。","importance":6},{"title":"WordPressにプラグインなしでGoogle翻訳を組み込んだメモ【インバウンド向け】","url":"https://zenn.dev/noboo/articles/289c07479497e0","source":"Zenn","published_at":"2026-11-20 13:45","genre":"web","genre_label":"Web開発・言語","headline":"WordPressにプラグインなしでGoogle翻訳を実装する手法","summary":"WordPressサイトにプラグインを使用せず、functions.phpへの直書きでGoogle翻訳を組み込む方法が解説されています。プラグインによるデータベース肥大化やセキュリティリスクを避け、軽量かつシンプルに多言語対応を実現します。\n\nブラウザの言語設定に応じた自動切り替えや、不要なUI要素の非表示処理をCSS/JSで制御することで、ユーザー体験を損なわない実装が可能です。インバウンド向けなど、簡易的な多言語対応が必要なケースにおいて、保守コストを抑えた実用的なアプローチです。","importance":5},{"title":"Tailscale を再起動したらノードが孤立した ― flannel VXLAN の不具合を直して upstream に出すまで","url":"https://zenn.dev/ryan0215/articles/flannel-vxlan-lease-replay","source":"Zenn","published_at":"2026-11-20 13:24","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Tailscale再起動でk3sノードが孤立するflannelの不具合を修正","summary":"Tailscaleの更新や再起動に伴い、k3sクラスタ内のノードが他ノードと通信不能になる不具合が発生。原因はflannelのVXLANバックエンドが、外部インターフェース再作成時にルートやARPエントリを復元しない仕様にあった。\n\n修正PRでは、インターフェース再作成時にリース情報を再適用するロジックを追加し、テストコードも整備した。この修正はflannel v0.28.11に含まれる。VPNインターフェースをflannel-ifaceに指定している環境での同様の事象に対する重要な知見である。","importance":8},{"title":"CLAUDE.md や SKILL.md のルールを Turtle で書き、ルールの書き間違いや矛盾を lint で検査してみた話","url":"https://zenn.dev/hma2moto/articles/turtle-agent-rules-pros-cons","source":"Zenn","published_at":"2026-11-19 23:13","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeのルール管理にTurtle形式を採用し矛盾を自動検査する","summary":"エージェントの行動ルールを記述するCLAUDE.mdやSKILL.mdにおいて、Markdownの代わりにTurtle形式を採用する試み。ルール間の関係性や強さを機械可読な形式で定義することで、ルールの矛盾や抜け漏れをlintで自動検査可能にした。\n\nRFC 2119に基づいた強さの定義や、例外・理由の構造化により、エージェントの遵守率が向上。曖昧な記述を排除し、ルールを論理的に管理する手法として有効である。","importance":7},{"title":"Claude Code の起動時に依存パッケージの脆弱性を調べるハーネスを、既製品と比べたうえで自作した話","url":"https://zenn.dev/no215/articles/claude-code-security-guardrail","source":"Zenn","published_at":"2026-11-20 09:01","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Claude Code起動時に依存パッケージの脆弱性を自動検知する仕組み","summary":"Claude Codeの起動時に、リポジトリの依存パッケージの脆弱性を自動でチェックする仕組みを自作。osv-scannerをバックエンドに採用し、1日1回の脅威DB更新と、起動時のフックによる照合を組み合わせることで、効率的かつ安全な検知環境を構築した。\n\n既製品との比較検討を経て、あえて自作した理由（取得頻度の制御や秘密情報検査との統合）を明確化。開発環境のセキュリティを自動化しつつ、トークン消費や通信を最適化する実践的なアプローチである。","importance":8},{"title":"1ターンだけ Sonnet に任せるスキルを作ったら、Opus のままより高くついていた話","url":"https://zenn.dev/no215/articles/claude-code-one-turn-model-skill","source":"Zenn","published_at":"2026-11-19 22:06","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Claude Codeでモデルを切り替えるスキルの費用対効果を検証","summary":"Claude Codeで特定のターンのみ下位モデル（Haiku/Sonnet）へ切り替えるスキルを作成し、費用を検証。Haikuはコスト削減に寄与したが、Sonnetへの切り替えは履歴の再書き込みコストにより、Opusを使い続けるより高額になるケースが判明した。\n\nモデル切り替え時にキャッシュが効かなくなる仕様がコスト増の要因であり、会話の長さやキャッシュの仕組みを考慮したモデル選択の重要性が示された。","importance":6}]};
